from taf.ue.tm500.asc.factory import create_shell
from taf.ue.tm500.asc.exception import NoGroupInUse


class asc:
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def set_username(self, name, connection=None, timeout=None):
        """
        set cobham username

        :param name: user name
        :param connection: ssh connection alias
        :param timeout: timeout for reading output
        """
        asc_shell = create_shell(connection)
        return asc_shell.UserName(name=name, timeout=timeout)

    def show_groups(self, connection=None, timeout=None):
        """
        show information of all groups

        :param connection: ssh connection alias
        :param timeout: timeout for reading output
        :return List[tuple]: format [(<groupname>, <username>, <data>]
        e.g. [('AllUnits', 'tm500', '.LP... 0 0000 0000 01F_001 13 On'),]
        """
        asc_shell = create_shell(connection)
        return asc_shell.ShowGroups(timeout=timeout)

    def lock_group(self, name, connection=None, timeout=None):
        """
        lock cobham group

        :param group_name: group name
        :param connection: ssh connection alias
        :param timeout: timeout for reading output
        """
        asc_shell = create_shell(connection)
        return asc_shell.LockGroup(name=name, timeout=timeout)

    def get_group_in_use(self, connection=None, timeout=None):
        """
        get the group in use, there should be only one group in use at most

        :param connection: ssh connection alias
        :param timeout: timeout for reading output
        :return str: group name
        """

        groups = self.show_groups(connection, timeout=timeout)
        for group in groups:
            if 'Power On' == self.show_power(group_name=group[0], connection=connection, timeout=timeout):
                return group[0]
        else:
            raise NoGroupInUse()

    def unlock_group(self, name, connection=None, timeout=None):
        """
        unlock cobham group

        :param group_name: group name
        :param connection: ssh connection alias
        :param timeout: timeout for reading output
        """
        asc_shell = create_shell(connection)
        return asc_shell.UnlockGroup(name=name, timeout=timeout)

    def show_power(self, group_name, connection=None, timeout=None):
        """
        show group power status

        :param group_name: group name
        :param connection: ssh connection alias
        :param timeout: timeout for reading output
        :return str: 'Power On' or 'Power Off'
        :exception: ASCResponseError or NoResourceNameFound
        """
        asc_shell = create_shell(connection)
        return asc_shell.ShowPower(group_name=group_name, timeout=timeout)

    def set_power_on(self, group_name, connection=None, timeout=None):
        """
        power on cobham

        :param group_name: group name
        :param connection: ssh connection alias
        :param timeout: timeout for reading output
        """
        asc_shell = create_shell(connection)
        return asc_shell.SetPowerOn(group_name=group_name, timeout=timeout)

    def set_power_off(self, group_name, connection=None, timeout=None):
        """
        power off cobham

        :param group_name: group name
        :param connection: ssh connection alias
        :param timeout: timeout for reading output
        """
        asc_shell = create_shell(connection)
        return asc_shell.SetPowerOff(group_name=group_name, timeout=timeout)

    def execute_command(self, command, connection=None, timeout=None):
        """
        execute asc command on cobham

        :param command: command string
        :param connection: ssh connection alias
        :param timeout: timeout for reading output
        """
        asc_shell = create_shell(connection)
        return asc_shell.RandomCommand(command=command, timeout=timeout)
